import { workspaceStorage } from '../portable/workspace-context.js';
import { useSessionCheckpoint } from '../store/useSessionCheckpoint.js';
import { useCallback, useEffect, useMemo, useRef, useState, type PointerEvent as ReactPointerEvent } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import JSZip from 'jszip';
import {
  JobQueue, PODCAST_FORMATS, checkPodcastEpisode, clock, completeRecipeProduction, createPodcastProject, effectivePodcastArtworkId, makePodcastClip, makePodcastSegment,
  podcastClipDuration, podcastDuration, podcastProblems, podcastShowNotes, PODCAST_SEGMENT_KINDS,
  PODCAST_VOICE_PRESETS, prosePlainText, resolveStoryCreationRecipe, saveDeliverable, segmentChapters, splitPodcastClip,
  type Asset, type Deliverable, type PodcastClip, type PodcastEpisodeFinding, type PodcastFormatId, type PodcastProject, type PodcastSegmentKind,
  type PodcastShow, type PodcastTrack, type Story, type Take, type Transcript, type User,
} from '@chatter/shared';
