type Station = 'RUNDOWN' | 'RECORD' | 'CUT' | 'MIX' | 'PACKAGE';
type Notice = { text: string; error?: boolean };
type AudioChoice = { assetId: string; title: string; durationSec?: number; source: string; storyId?: string };
type TranscriptPart = { start: number; end: number; text: string };

const STATIONS: Array<{ id: Station; label: string; verb: string; icon: string }> = [
  { id: 'RUNDOWN', label: 'Rundown', verb: 'Plan the show', icon: '▤' },
  { id: 'RECORD', label: 'Record', verb: 'Capture voices', icon: '●' },
  { id: 'CUT', label: 'Cut', verb: 'Shape the episode', icon: '✂' },
  { id: 'MIX', label: 'Mix', verb: 'Balance the sound', icon: '≋' },
  { id: 'PACKAGE', label: 'Package', verb: 'Check and hand off', icon: '▣' },
];
const TRACK_ICONS: Record<PodcastTrack['kind'], string> = { VOICE: '◖))', MUSIC: '♫', SFX: '✦', AMBIENCE: '≈' };
function omitBase<T extends { id: string; createdAt: number; updatedAt: number }>(value: T): Omit<T, 'id' | 'createdAt' | 'updatedAt'> { const { id: _id, createdAt: _createdAt, updatedAt: _updatedAt, ...rest } = value; return rest; }
function safeName(value: string) { return value.trim().replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').toLowerCase() || 'chatterbox-episode'; }
function download(blob: Blob, name: string) { const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = name; link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1200); }
function targetTime(segments: PodcastProject['segments']) { return segments.reduce((sum, segment) => sum + segment.targetSec, 0); }
function segmentLabel(kind: PodcastSegmentKind) { return PODCAST_SEGMENT_KINDS.find((item) => item.kind === kind)?.label ?? 'Segment'; }

function RecordTakeBench({ clips, urls, selectedId, onSelect, onUpdate, onMove, onPack, onRemove, onOpenCut }: {
  clips: PodcastClip[];
  urls: Map<string, string>;
  selectedId?: string;
  onSelect: (id: string) => void;
  onUpdate: (id: string, patch: Partial<PodcastClip>) => void;
  onMove: (id: string, delta: number) => void;
  onPack: () => void;
  onRemove: (id: string) => void;
  onOpenCut: () => void;
}) {
  const ordered = [...clips].sort((a, b) => a.startSec - b.startSec);
  const selected = ordered.find((clip) => clip.id === selectedId) ?? ordered.at(-1);
  const player = useRef<HTMLAudioElement>(null);
  const source = selected ? urls.get(selected.assetId) : undefined;

  function cueTrimmedTake() {
    const audio = player.current;
    if (!audio || !selected) return;
    audio.currentTime = selected.trimInSec;
    void audio.play();
  }

  return <section className="chatterbox-take-bench">
    <header><div><span className="newsroom-eyebrow">TAKE ASSEMBLY</span><h2>Build the clean read while you record</h2><p>Pick the best pieces, trim the edges, and put the takes in speaking order.</p></div><div><button disabled={ordered.length < 2} onClick={onPack}>Snap takes together</button><button className="newsroom-button primary" onClick={onOpenCut}>Open the full Cut →</button></div></header>
    {ordered.length ? <>
      <div className="chatterbox-take-strip" aria-label="Recorded take timeline">{ordered.map((clip, index) => <button key={clip.id} aria-current={selected?.id === clip.id} style={{ flexGrow: Math.max(1, podcastClipDuration(clip)) }} onClick={() => onSelect(clip.id)}><i>{index + 1}</i><span>{clip.name}</span><small>{clock(podcastClipDuration(clip))}</small></button>)}</div>
      {selected && <div className="chatterbox-take-editor"><div><b>Take {ordered.findIndex((clip) => clip.id === selected.id) + 1} · {selected.name}</b><span>{clock(selected.trimInSec)} → {clock(selected.trimOutSec)}</span></div>{source ? <audio ref={player} controls src={source} onLoadedMetadata={(event) => { event.currentTarget.currentTime = selected.trimInSec; }} onPlay={(event) => { if (event.currentTarget.currentTime < selected.trimInSec || event.currentTarget.currentTime >= selected.trimOutSec) event.currentTarget.currentTime = selected.trimInSec; }} onTimeUpdate={(event) => { if (event.currentTarget.currentTime >= selected.trimOutSec) event.currentTarget.pause(); }} /> : <span className="chatterbox-take-missing">Reading this take…</span>}<div className="chatterbox-take-trims"><label>Start<input type="range" min={0} max={Math.max(0, selected.trimOutSec - .05)} step={.05} value={selected.trimInSec} onChange={(event) => onUpdate(selected.id, { trimInSec: Number(event.target.value) })} /><b>{selected.trimInSec.toFixed(2)}s</b></label><label>End<input type="range" min={selected.trimInSec + .05} max={selected.sourceDurationSec} step={.05} value={selected.trimOutSec} onChange={(event) => onUpdate(selected.id, { trimOutSec: Number(event.target.value) })} /><b>{selected.trimOutSec.toFixed(2)}s</b></label></div><div className="chatterbox-take-actions"><button onClick={cueTrimmedTake} disabled={!source}>▶ Play trimmed take</button><button onClick={() => onMove(selected.id, -1)} disabled={ordered[0]?.id === selected.id}>← Earlier</button><button onClick={() => onMove(selected.id, 1)} disabled={ordered.at(-1)?.id === selected.id}>Later →</button><button className="danger" onClick={() => onRemove(selected.id)}>Remove</button></div></div>}
    </> : <div className="chatterbox-take-empty"><span>●</span><div><b>Your takes will line up here.</b><p>Record or bring in a voice, then make a quick assembly without leaving the mic.</p></div></div>}
  </section>;
}

export function Chatterbox({ stories, me }: { stories: Story[]; me?: User }) {
  const store = useStore(); const { gate } = useGate(); const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams(); const requestedProjectId = searchParams.get('project'); const requestedStoryId = searchParams.get('story');
  const [station, setStation] = useState<Station>('RUNDOWN'); const [shows, setShows] = useState<PodcastShow[]>([]); const [projects, setProjects] = useState<PodcastProject[]>([]); const [show, setShow] = useState<PodcastShow>(); const [project, setProject] = useState<PodcastProject>();
  const [assets, setAssets] = useState<Asset[]>([]); const [takes, setTakes] = useState<Take[]>([]); const [deliverables, setDeliverables] = useState<Deliverable[]>([]); const [transcripts, setTranscripts] = useState<Transcript[]>([]); const [audioUrls, setAudioUrls] = useState<Map<string, string>>(new Map());
  const [selectedClipId, setSelectedClipId] = useState<string>(); const [selectedTrackId, setSelectedTrackId] = useState<string>(); const [selectedStoryId, setSelectedStoryId] = useState(''); const [selectedSourceId, setSelectedSourceId] = useState(''); const [notice, setNotice] = useState<Notice>(); const [busy, setBusy] = useState(''); const [dirty, setDirty] = useState(false); const [showDirty, setShowDirty] = useState(false); const [showEpisodeCheck, setShowEpisodeCheck] = useState(false); const [showCoverStudio, setShowCoverStudio] = useState(false); const saveTimer = useRef<number>(); const showTimer = useRef<number>();
  const [reilyProblem, setReilyProblem] = useState<'import' | 'export'>();
  const projectRef = useRef<PodcastProject>(); const showRef = useRef<PodcastShow>(); const dirtyRef = useRef(false); const showDirtyRef = useRef(false); const projectVersion = useRef(0); const showVersion = useRef(0);
  const openingRef = useRef<Promise<void>>();
  const [starter, setStarter] = useState(false);
  const [countIn, setCountIn] = useState(3); const [recordTrackId, setRecordTrackId] = useState(''); const [playhead, setPlayhead] = useState(0); const [zoom, setZoom] = useState(8); const [wave, setWave] = useState<number[]>([]); const previewAudio = useRef<HTMLAudioElement>(null); const timelineAudio = useRef<HTMLAudioElement>(null); const importPicker = useRef<HTMLInputElement>(null); const newEpisodeMenu = useRef<HTMLDetailsElement>(null);
  const [timelinePlaying, setTimelinePlaying] = useState(false);
  const [rendered, setRendered] = useState<PodcastRenderResult>(); const [previewUrl, setPreviewUrl] = useState(''); const [renderProgress, setRenderProgress] = useState<number>(); const [lastPackage, setLastPackage] = useState<Blob>();

  const reload = useCallback(async () => {
    const [nextShows, nextProjects, nextAssets, nextTakes, nextFiles, nextTranscripts] = await Promise.all([store.podcastShows.list(), store.podcastProjects.list(), store.assets.list(), store.takes.list(), store.deliverables.list(), store.transcripts.list()]);
    setShows(nextShows.sort((a, b) => b.updatedAt - a.updatedAt)); setProjects(nextProjects.sort((a, b) => b.updatedAt - a.updatedAt)); setAssets(nextAssets); setTakes(nextTakes); setDeliverables(nextFiles); setTranscripts(nextTranscripts);
    return { nextShows, nextProjects };
  }, [store]);

  useEffect(() => {
    let live = true;
    const opening = (async () => {
      await flushDrafts();
      const ready = await ensurePodcastWorkspace(store, { authorId: me?.id, requestedProjectId, requestedStoryId, rememberedProjectId: readActivePodcastId(workspaceStorage(window.sessionStorage)) });
      const loaded = await reload();
      if (!live) return;
      showRef.current = ready.show; projectRef.current = ready.project;
      dirtyRef.current = ready.unsavedProject; showDirtyRef.current = ready.unsavedShow;
      setShow(ready.show); setProject(ready.project); setDirty(ready.unsavedProject); setShowDirty(ready.unsavedShow); setStarter(ready.starter);
      setShows(loaded.nextShows); setProjects(loaded.nextProjects);
      setRecordTrackId(ready.project.tracks.find((track) => track.kind === 'VOICE')?.id ?? '');
      if (!ready.starter) rememberActivePodcastId(workspaceStorage(window.sessionStorage), ready.project.id);
    })();
    openingRef.current = opening;
    void opening.catch((error) => { if (live) setNotice({ text: error instanceof Error ? error.message : 'Chatterbox did not open.', error: true }); });
    return () => { live = false; };
  }, [reload, store, me?.id, requestedProjectId, requestedStoryId]);
  useEffect(() => { if (requestedStoryId && stories.some((story) => story.id === requestedStoryId) && !project?.storyIds.includes(requestedStoryId)) setSelectedStoryId(requestedStoryId); }, [project?.storyIds, requestedStoryId, stories]);

  useEffect(() => { if (!dirty || !project) return; const version = projectVersion.current; window.clearTimeout(saveTimer.current); saveTimer.current = window.setTimeout(() => { void savePodcastProject(store, project).then((saved) => { if (projectVersion.current !== version || projectRef.current?.id !== saved.id) return; projectRef.current = saved; dirtyRef.current = false; setProject(saved); setProjects((rows) => [saved, ...rows.filter((item) => item.id !== saved.id)]); setDirty(false); setStarter(false); rememberActivePodcastId(workspaceStorage(window.sessionStorage), saved.id); }).catch(() => setNotice({ text: 'The episode did not save. Your changes remain in this tab.', error: true })); }, 650); return () => window.clearTimeout(saveTimer.current); }, [dirty, project, store]);
  useEffect(() => { if (!showDirty || !show) return; const version = showVersion.current; window.clearTimeout(showTimer.current); showTimer.current = window.setTimeout(() => { void savePodcastShow(store, show).then((saved) => { if (showVersion.current !== version || showRef.current?.id !== saved.id) return; showRef.current = saved; showDirtyRef.current = false; setShow(saved); setShowDirty(false); }).catch(() => setNotice({ text: 'The show setup did not save. Try the change again.', error: true })); }, 650); return () => window.clearTimeout(showTimer.current); }, [showDirty, show, store]);
  useEffect(() => () => {
    window.clearTimeout(saveTimer.current); window.clearTimeout(showTimer.current);
    const episodeDraft = projectRef.current; const showDraft = showRef.current;
    if (dirtyRef.current && episodeDraft) void savePodcastProject(store, episodeDraft);
    if (showDirtyRef.current && showDraft) void savePodcastShow(store, showDraft);
  }, [store]);
  useEffect(() => { const made: string[] = []; let live = true; void (async () => { const media = new Map<string, string>(); for (const asset of assets.filter((item) => ['AUDIO', 'IMAGE'].includes(item.kind) && item.gateStatus === 'APPROVED')) { const bytes = await store.blobs.get(asset.sha256); if (!bytes) continue; const url = URL.createObjectURL(new Blob([bytes as unknown as BlobPart], { type: asset.mime })); made.push(url); media.set(asset.id, url); } if (live) setAudioUrls(media); })(); return () => { live = false; made.forEach((url) => URL.revokeObjectURL(url)); }; }, [assets, store]);
  useEffect(() => { return () => { if (previewUrl) URL.revokeObjectURL(previewUrl); }; }, [previewUrl]);

  function commit(recipe: (draft: PodcastProject) => void) { const current = projectRef.current; if (!current) return; const next = structuredClone(current); recipe(next); next.updatedAt = Date.now(); projectRef.current = next; dirtyRef.current = true; projectVersion.current += 1; setProject(next); setDirty(true); setRendered(undefined); setLastPackage(undefined); }
  function commitShow(recipe: (draft: PodcastShow) => void) { const current = showRef.current; if (!current) return; const next = structuredClone(current); recipe(next); next.updatedAt = Date.now(); showRef.current = next; showDirtyRef.current = true; showVersion.current += 1; setShow(next); setShowDirty(true); if (starter) commit(() => {}); }

  async function flushDrafts() {
    window.clearTimeout(saveTimer.current); window.clearTimeout(showTimer.current);
    const episodeDraft = projectRef.current; const episodeVersion = projectVersion.current; const activeShow = showRef.current; const activeShowVersion = showVersion.current;
    if (dirtyRef.current && episodeDraft) { const saved = await savePodcastProject(store, episodeDraft); if (projectVersion.current === episodeVersion && projectRef.current?.id === saved.id) { projectRef.current = saved; dirtyRef.current = false; setProject(saved); setProjects((rows) => [saved, ...rows.filter((item) => item.id !== saved.id)]); setDirty(false); setStarter(false); rememberActivePodcastId(workspaceStorage(window.sessionStorage), saved.id); } }
    if (showDirtyRef.current && activeShow) { const saved = await savePodcastShow(store, activeShow); if (showVersion.current === activeShowVersion && showRef.current?.id === saved.id) { showRef.current = saved; showDirtyRef.current = false; setShow(saved); setShows((rows) => rows.map((item) => item.id === saved.id ? saved : item)); setShowDirty(false); } }
  }

  async function switchProject(next: PodcastProject) { if (next.id === projectRef.current?.id) return; setBusy('Saving current episode…'); try { await flushDrafts(); const nextShow = shows.find((item) => item.id === next.showId); if (nextShow) { showRef.current = nextShow; showDirtyRef.current = false; setShow(nextShow); setShowDirty(false); } projectRef.current = next; dirtyRef.current = false; setProject(next); setDirty(false); setStarter(false); rememberActivePodcastId(workspaceStorage(window.sessionStorage), next.id); setSearchParams({ project: next.id }, { replace: true }); setRecordTrackId(next.tracks.find((track) => track.kind === 'VOICE')?.id ?? ''); setSelectedClipId(undefined); setNotice(undefined); } catch (error) { setNotice({ text: error instanceof Error ? error.message : 'The current episode did not save, so Chatterbox kept it open.', error: true }); } finally { setBusy(''); } }

  async function newEpisode(template: PodcastFormatId | 'TRAILER') { if (!showRef.current) return; setBusy('Starting episode…'); try { await flushDrafts(); const activeShow = (await store.podcastShows.get(showRef.current!.id))!; const draft = createPodcastProject(activeShow, { template, authorId: me?.id }); const saved = await store.podcastProjects.create(omitBase(draft)); const updatedShow = await store.podcastShows.update(activeShow.id, { nextEpisodeNumber: activeShow.nextEpisodeNumber + 1 }); showRef.current = updatedShow; projectRef.current = saved; dirtyRef.current = false; showDirtyRef.current = false; setShow(updatedShow); setShowDirty(false); setProjects((rows) => [saved, ...rows]); setProject(saved); setDirty(false); setStarter(false); rememberActivePodcastId(workspaceStorage(window.sessionStorage), saved.id); setSearchParams({ project: saved.id }, { replace: true }); setStation('RUNDOWN'); setSelectedClipId(undefined); setRecordTrackId(saved.tracks[0]?.id ?? ''); newEpisodeMenu.current?.removeAttribute('open'); setNotice({ text: `${saved.title} is on the board. Build the rundown from left to right.` }); } finally { setBusy(''); } }

  const choices = useMemo<AudioChoice[]>(() => {
    const map = new Map<string, AudioChoice>();
    for (const take of takes) { const id = take.renderedAssetId ?? take.assetId; const story = stories.find((item) => item.id === take.storyId); map.set(id, { assetId: id, title: take.name || `${story?.title ?? 'Story'} take`, durationSec: take.edits ? take.edits.trimEnd - take.edits.trimStart : take.durationSec, source: 'Booth', storyId: take.storyId }); }
    for (const file of deliverables.filter((item) => item.kind === 'AUDIO' && item.sourceAssetId)) map.set(file.sourceAssetId!, { assetId: file.sourceAssetId!, title: file.title, durationSec: file.durationSec, source: file.room === 'GARAGE' ? 'Studio' : file.room === 'BOOTH' ? 'Booth' : file.room === 'CHATTERBOX' ? 'Chatterbox' : file.room, storyId: file.storyId });
    return [...map.values()].filter((item) => assets.find((asset) => asset.id === item.assetId)?.gateStatus === 'APPROVED').sort((a, b) => a.source.localeCompare(b.source) || a.title.localeCompare(b.title));
  }, [takes, deliverables, stories, assets]);
  const selectedClip = project?.clips.find((clip) => clip.id === selectedClipId); const selectedTrack = project?.tracks.find((track) => track.id === (selectedClip?.trackId ?? selectedTrackId)); const transcript = transcripts.find((item) => item.assetId === selectedClip?.assetId); const transcriptParts = (transcript?.segments ?? []) as TranscriptPart[];
  const duration = project ? podcastDuration(project) : 0; const planDuration = project ? targetTime(project.segments) : 0; const timelineSec = Math.max(60, duration + 20, planDuration); const timelineWidth = Math.max(780, timelineSec * zoom);
  const recordClips = project?.clips.filter((clip) => clip.trackId === recordTrackId) ?? [];
  const coverChoices = useMemo<PodcastCoverChoice[]>(() => { const storyIds = new Set(project?.storyIds ?? []); const labeled = new Map<string, PodcastCoverChoice>(); for (const file of deliverables.filter((item) => (item.kind === 'IMAGE' || item.kind === 'DESIGN') && item.sourceAssetId && (!item.storyId || storyIds.has(item.storyId)))) labeled.set(file.sourceAssetId!, { assetId: file.sourceAssetId!, title: file.title, source: file.room === 'BLAST' ? 'Blast' : 'Media Bin' }); for (const asset of assets.filter((item) => item.kind === 'IMAGE' && item.gateStatus === 'APPROVED')) if (!labeled.has(asset.id)) labeled.set(asset.id, { assetId: asset.id, title: asset.creator || 'Approved image', source: asset.origin === 'GENERATED' ? 'Blast' : 'Media Bin' }); return [...labeled.values()]; }, [assets, deliverables, project?.storyIds]);
  const effectiveCoverId = project && show ? effectivePodcastArtworkId(project, show) : undefined;
  const episodeFindings = useMemo(() => project && show ? checkPodcastEpisode(project, show) : [], [project, show]);

  useEffect(() => { let live = true; setWave([]); if (!selectedClip) return; void (async () => { const asset = await store.assets.get(selectedClip.assetId); if (!asset) return; const bytes = await store.blobs.get(asset.sha256); if (!bytes) return; const decoded = await decodeTakeAudio(bytes); if (live) setWave(waveformPeaks(decoded, 180)); })().catch(() => undefined); return () => { live = false; }; }, [selectedClip?.id, selectedClip?.assetId, store]);

  async function addChoice(choice: AudioChoice, trackId?: string) { if (!project) return; setBusy('Reading audio…'); try { let seconds = choice.durationSec; if (!seconds) { const asset = await store.assets.get(choice.assetId); const bytes = asset ? await store.blobs.get(asset.sha256) : undefined; if (!bytes) throw new Error('That recording is missing from this computer.'); seconds = (await decodeTakeAudio(bytes)).duration; } const target = trackId ?? project.tracks.find((track) => choice.source === 'Studio' ? track.kind === 'MUSIC' : track.kind === 'VOICE')?.id ?? project.tracks[0]!.id; const clip = makePodcastClip({ assetId: choice.assetId, trackId: target, name: choice.title, durationSec: seconds, startSec: duration }); commit((draft) => { draft.clips.push(clip); if (choice.storyId && !draft.storyIds.includes(choice.storyId)) draft.storyIds.push(choice.storyId); }); setSelectedClipId(clip.id); setStation('CUT'); setNotice({ text: `${choice.title} is in the cut at ${clock(duration)}.` }); } catch (error) { setNotice({ text: error instanceof Error ? error.message : 'That audio could not be added.', error: true }); } finally { setBusy(''); } }

  async function saveCaptured(capture: CapturedTake) { if (!project) return; await ingestAudio(capture.blob, `Host take · ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`, 'RECORDING', capture.duration, capture.captureId); }
  useSessionCheckpoint(store, async () => {
    if (busy || recorder.error || ['COUNTDOWN', 'RECORDING', 'PAUSED', 'SAVING', 'ASKING'].includes(recorder.phase)) throw new Error('Resolve any Chatterbox recorder error, stop and save the recording, or wait for its current job, then retry.');
    await openingRef.current;
    await flushDrafts();
  });

  const recorder = useBoothRecorder(saveCaptured);
  useReilyFocus(chatterboxReilyFocus(station));
  const chatterboxProblem = reilyProblem ?? (station === 'PACKAGE' && notice?.error ? 'export' : undefined);
  const chatterboxRecovery = recorder.error
    ? chatterboxReilyRecovery('microphone')
    : chatterboxProblem ? chatterboxReilyRecovery(chatterboxProblem) : undefined;
  useReilyRecovery(chatterboxRecovery ? { kind: chatterboxRecovery, workChanged: false } : undefined);
  async function ingestAudio(blob: Blob, title: string, origin: 'RECORDING' | 'UPLOAD', knownDuration?: number, captureId?: string) { if (!project) return; setBusy('Saving audio…'); setNotice(undefined); if (origin === 'UPLOAD') setReilyProblem(undefined); try { const bytes = new Uint8Array(await blob.arrayBuffer()); const decodedDuration = knownDuration ?? (await decodeTakeAudio(bytes)).duration; if (decodedDuration > 60 * 60) throw new Error('Use recordings under one hour. Split a longer session into parts.'); const result = await gate.ingest({ source: origin === 'RECORDING' ? 'recording' : 'upload', bytes, ownDevice: origin === 'RECORDING', meta: { kind: 'AUDIO', mime: blob.type || 'audio/webm', origin, storyId: project.storyIds[0], actor: me?.id, creator: 'Chatterbox crew', license: 'OWN' } }); if (!result.assetId) throw new Error('The recording could not enter this episode.'); if (result.status !== 'APPROVED') { await reload(); setNotice({ text: `${title} is saved and waiting for an adviser’s media check. It will appear in the palette after approval.` }); return; } const extension = blob.type.includes('wav') ? 'wav' : blob.type.includes('mp4') ? 'm4a' : blob.type.includes('ogg') ? 'ogg' : 'webm'; await saveDeliverable(store, { bytes, title, fileName: `${safeName(title)}.${extension}`, kind: 'AUDIO', room: 'CHATTERBOX', stage: 'WORKING', mime: blob.type || 'audio/webm', storyId: project.storyIds[0], authorId: me?.id, sourceAssetId: result.assetId, sourceProjectId: project.id, durationSec: decodedDuration }); await new JobQueue(store).enqueue('transcribe', { assetId: result.assetId, ...(captureId ? { captureId } : {}) }); const clip = makePodcastClip({ assetId: result.assetId, trackId: recordTrackId || project.tracks[0]!.id, name: title, durationSec: decodedDuration, startSec: duration }); commit((draft) => draft.clips.push(clip)); setSelectedClipId(clip.id); await reload(); setNotice({ text: `${title} is saved, placed at ${clock(duration)}, and queued for a transcript.` }); } catch (error) { if (origin === 'UPLOAD') setReilyProblem('import'); setNotice({ text: error instanceof Error ? error.message : 'The recording did not save. Download it before leaving this tab.', error: true }); throw error; } finally { setBusy(''); } }
  async function importAudio(file: File) { if (!file.size || file.size > 500 * 1024 * 1024) { setReilyProblem('import'); setNotice({ text: 'Choose a non-empty audio file under 500 MB.', error: true }); return; } try { await ingestAudio(file, file.name.replace(/\.[^.]+$/, ''), 'UPLOAD'); } catch { /* ingestAudio keeps the visible error and Reily recovery state. */ } finally { if (importPicker.current) importPicker.current.value = ''; } }

  function addStorySegment() { const story = stories.find((item) => item.id === selectedStoryId); if (!story) return; const segment = makePodcastSegment('STORY', { story }); segment.script = prosePlainText(story.body); commit((draft) => { draft.segments.push(segment); if (!draft.storyIds.includes(story.id)) draft.storyIds.push(story.id); }); setSelectedStoryId(''); }
  function addSegment(kind: PodcastSegmentKind) { commit((draft) => draft.segments.push(makePodcastSegment(kind))); }
  function moveSegment(id: string, delta: number) { commit((draft) => { const at = draft.segments.findIndex((item) => item.id === id); const to = Math.max(0, Math.min(draft.segments.length - 1, at + delta)); if (at === to) return; const [item] = draft.segments.splice(at, 1); draft.segments.splice(to, 0, item!); }); }
  function updateTrack(id: string, patch: Partial<PodcastTrack>) { commit((draft) => { const track = draft.tracks.find((item) => item.id === id); if (track) Object.assign(track, patch); }); }
  function updateClip(id: string, patch: Partial<PodcastClip>) { commit((draft) => { const clip = draft.clips.find((item) => item.id === id); if (clip) Object.assign(clip, patch); }); }
  function toggleTranscriptPart(part: TranscriptPart) { if (!selectedClip) return; const removed = selectedClip.omittedRanges.some((range) => range.start <= part.start + .01 && range.end >= part.end - .01); updateClip(selectedClip.id, { omittedRanges: removed ? selectedClip.omittedRanges.filter((range) => !(range.start <= part.start + .01 && range.end >= part.end - .01)) : [...selectedClip.omittedRanges, { start: part.start, end: part.end }] }); }
  function splitSelected() { if (!project || !selectedClip) return; const parts = splitPodcastClip(selectedClip, playhead); if (!parts) { setNotice({ text: 'Put the playhead inside the selected clip before splitting.', error: true }); return; } commit((draft) => { const at = draft.clips.findIndex((item) => item.id === selectedClip.id); draft.clips.splice(at, 1, ...parts); }); setSelectedClipId(parts[1].id); }
  function arrangeRecordTakes(movingId?: string, delta = 0) { commit((draft) => { const ordered = draft.clips.filter((clip) => clip.trackId === recordTrackId).sort((a, b) => a.startSec - b.startSec); if (movingId) { const from = ordered.findIndex((clip) => clip.id === movingId); const to = Math.max(0, Math.min(ordered.length - 1, from + delta)); if (from >= 0 && from !== to) { const [moved] = ordered.splice(from, 1); ordered.splice(to, 0, moved!); } } let cursor = 0; for (const clip of ordered) { clip.startSec = Math.round(cursor * 100) / 100; cursor += podcastClipDuration(clip); } }); }
  function removeRecordTake(id: string) { commit((draft) => { draft.clips = draft.clips.filter((clip) => clip.id !== id); }); if (selectedClipId === id) setSelectedClipId(undefined); }
  function beginClipDrag(event: ReactPointerEvent, clip: PodcastClip) {
    if (event.button !== 0) return;
    event.preventDefault(); setSelectedClipId(clip.id);
    const startX = event.clientX; const original = clip.startSec;
    const move = (next: PointerEvent) => updateClip(clip.id, { startSec: Math.max(0, Math.round((original + (next.clientX - startX) / zoom) * 10) / 10) });
    const up = () => {
      window.removeEventListener('pointermove', move);
      window.removeEventListener('pointerup', up);
      window.removeEventListener('pointercancel', up);
    };
    window.addEventListener('pointermove', move);
    window.addEventListener('pointerup', up);
    window.addEventListener('pointercancel', up);
  }

  function focusEpisodeFinding(finding: PodcastEpisodeFinding) { setStation(finding.station); setShowEpisodeCheck(false); if (finding.clipId) setSelectedClipId(finding.clipId); if (finding.trackId) setSelectedTrackId(finding.trackId); if (finding.atSec !== undefined) setPlayhead(finding.atSec); if (finding.code === 'missing-cover') setShowCoverStudio(true); }

  async function uploadCover(file: File) {
    if (!project || !file.size || file.size > 50 * 1024 * 1024) { setNotice({ text: 'Choose a non-empty image under 50 MB.', error: true }); return; }
    setBusy('Saving cover…'); setNotice(undefined);
    try {
      const bytes = new Uint8Array(await file.arrayBuffer());
      const result = await gate.ingest({ source: 'upload', bytes, meta: { kind: 'IMAGE', mime: file.type || 'image/png', origin: 'UPLOAD', storyId: project.storyIds[0], actor: me?.id, creator: me?.penName ?? 'Chatterbox crew', license: 'OWN' } });
      if (!result.assetId) throw new Error('That cover could not enter the episode.');
      if (result.status !== 'APPROVED') { await reload(); setNotice({ text: 'The cover is saved and waiting for an adviser’s media check.' }); return; }
      await saveDeliverable(store, { bytes, title: `${project.title} · cover`, fileName: file.name || `${safeName(project.title)}-cover.png`, kind: 'IMAGE', room: 'CHATTERBOX', stage: 'WORKING', mime: file.type || 'image/png', storyId: project.storyIds[0], authorId: me?.id, sourceAssetId: result.assetId, sourceProjectId: project.id });
      commit((draft) => { draft.artworkAssetId = result.assetId; draft.artworkMode = 'EPISODE'; });
      await reload(); setNotice({ text: 'Episode cover saved.' });
    } catch (error) { setNotice({ text: error instanceof Error ? error.message : 'The cover did not save.', error: true }); }
    finally { setBusy(''); }
  }

  async function editCoverInBlast() {
    if (!project || !show || busy) return;
    setBusy('Opening cover in Blast…');
    try {
      let blastId = project.coverBlastProjectId;
      if (blastId && !(await store.blasts.get(blastId))) blastId = undefined;
      if (!blastId) {
        const built = buildPodcastCoverProject({ showTitle: show.title, episodeTitle: project.title, episodeNumber: project.episodeNumber, artworkAssetId: effectiveCoverId });
        const created = await store.blasts.create({ ...built, ...(me?.id ? { authorId: me.id } : {}), ...(project.storyIds[0] ? { storyId: project.storyIds[0] } : {}) });
        blastId = created.id; commit((draft) => { draft.coverBlastProjectId = created.id; }); await flushDrafts();
      }
      navigate(podcastCoverHandoff(blastId, project.id));
    } catch (error) { setNotice({ text: error instanceof Error ? error.message : 'Blast could not open this cover.', error: true }); }
    finally { setBusy(''); }
  }

  async function sourceMap(): Promise<Map<string, PodcastSource>> { if (!project) return new Map(); const map = new Map<string, PodcastSource>(); for (const id of new Set(project.clips.map((clip) => clip.assetId))) { const asset = await store.assets.get(id); const bytes = asset ? await store.blobs.get(asset.sha256) : undefined; if (asset && bytes) map.set(id, { bytes, mime: asset.mime }); } return map; }
  async function makePreview(playAfter = false) {
    if (!project || busy) return;
    setBusy('Mixing preview…'); setRenderProgress(0); setNotice(undefined); setReilyProblem(undefined);
    try {
      const result = await renderPodcastMix(project, await sourceMap(), setRenderProgress);
      const blob = new Blob([encodeTakeWav(result.audio) as unknown as BlobPart], { type: 'audio/wav' });
      if (previewUrl) URL.revokeObjectURL(previewUrl);
      const nextUrl = URL.createObjectURL(blob);
      setPreviewUrl(nextUrl); setRendered(result);
      setNotice({ text: `Full cut ready · ${result.estimatedLufs.toFixed(1)} LUFS estimate · ${result.truePeakDb.toFixed(1)} dB peak.` });
      if (playAfter) window.setTimeout(() => { const audio = timelineAudio.current; if (!audio) return; audio.src = nextUrl; audio.currentTime = Math.min(playhead, result.audio.duration); void audio.play().catch(() => setNotice({ text: 'The full cut is ready. Press Play once more to hear it.' })); }, 0);
    } catch (error) { setReilyProblem('export'); setNotice({ text: error instanceof Error ? error.message : 'The preview could not be mixed.', error: true }); }
    finally { setBusy(''); setRenderProgress(undefined); }
  }
  function playFullCut() { const audio = timelineAudio.current; if (!project?.clips.length) { setNotice({ text: 'Record or place some audio before playing the cut.', error: true }); return; } if (!previewUrl || !rendered) { void makePreview(true); return; } if (!audio) return; audio.currentTime = Math.min(playhead, Math.max(0, duration - .01)); void audio.play(); }
  function stopFullCut() { const audio = timelineAudio.current; audio?.pause(); if (audio) audio.currentTime = 0; setPlayhead(0); setTimelinePlaying(false); }
  function visibleTranscript() { if (!project) return ''; return project.clips.flatMap((clip) => { const found = transcripts.find((item) => item.assetId === clip.assetId); const parts = (found?.segments ?? []) as TranscriptPart[]; if (!parts.length) return found?.text ? [`${clip.name}\n${found.text}`] : []; return [`${clip.name}\n${parts.filter((part) => !clip.omittedRanges.some((range) => range.start <= part.start + .01 && range.end >= part.end - .01)).map((part) => part.text.trim()).join(' ')}`]; }).join('\n\n'); }
  async function makePackage() { if (!project || !show || busy) return; const problems = [...podcastProblems(project), ...episodeFindings.filter((finding) => finding.severity === 'BLOCKING').map((finding) => finding.message)]; if (problems.length) { setNotice({ text: problems[0]!, error: true }); setShowEpisodeCheck(true); return; } setBusy('Building episode package…'); setRenderProgress(0); setNotice(undefined); try { const result = await renderPodcastMix(project, await sourceMap(), setRenderProgress); const wav = encodeTakeWav(result.audio); const notes = podcastShowNotes(project, show, stories); const transcriptText = visibleTranscript(); const base = safeName(project.title); const coverId = effectivePodcastArtworkId(project, show); const coverAsset = coverId ? await store.assets.get(coverId) : undefined; const coverBytes = coverAsset ? await store.blobs.get(coverAsset.path) : undefined; const coverExtension = coverAsset?.mime.includes('jpeg') ? 'jpg' : coverAsset?.mime.includes('webp') ? 'webp' : coverAsset?.mime.includes('gif') ? 'gif' : 'png'; const zip = new JSZip(); zip.file(`${base}.wav`, wav); if (coverBytes) zip.file(`${base}-cover.${coverExtension}`, coverBytes); zip.file(`${base}-show-notes.txt`, notes); zip.file(`${base}-transcript.txt`, transcriptText || 'Transcript not available yet.'); zip.file(`${base}-chapters.json`, JSON.stringify(project.chapters, null, 2)); zip.file(`${base}-episode.json`, JSON.stringify({ show: show.title, title: project.title, description: project.description, episodeType: project.episodeType, season: project.seasonNumber, episode: project.episodeNumber, explicit: project.explicit, artworkAssetId: coverId, coverFile: coverBytes ? `${base}-cover.${coverExtension}` : undefined, formatId: project.formatId, estimatedLufs: result.estimatedLufs, truePeakDb: result.truePeakDb }, null, 2)); const packageBlob = await zip.generateAsync({ type: 'blob', compression: 'DEFLATE', compressionOptions: { level: 5 } }); const wavResult = await gate.ingest({ source: 'generated', bytes: wav, ownDevice: true, meta: { kind: 'AUDIO', mime: 'audio/wav', origin: 'GENERATED', storyId: project.storyIds[0], actor: me?.id, creator: 'Chatterbox crew', license: 'OWN' } }); await saveDeliverable(store, { bytes: wav, title: `${project.title} · listening master`, fileName: `${base}.wav`, kind: 'AUDIO', room: 'CHATTERBOX', stage: 'REVIEW', mime: 'audio/wav', storyId: project.storyIds[0], authorId: me?.id, sourceAssetId: wavResult.assetId, sourceProjectId: project.id, durationSec: result.audio.duration }); await saveDeliverable(store, { bytes: new TextEncoder().encode(notes), title: `${project.title} · show notes`, fileName: `${base}-show-notes.txt`, kind: 'DOCUMENT', room: 'CHATTERBOX', stage: 'REVIEW', mime: 'text/plain', storyId: project.storyIds[0], authorId: me?.id, sourceProjectId: project.id }); await saveDeliverable(store, { bytes: new Uint8Array(await packageBlob.arrayBuffer()), title: `${project.title} · episode package`, fileName: `${base}-episode.zip`, kind: 'PACKAGE', room: 'CHATTERBOX', stage: 'REVIEW', mime: 'application/zip', storyId: project.storyIds[0], authorId: me?.id, sourceProjectId: project.id, durationSec: result.audio.duration }); commit((draft) => { draft.state = 'REVIEW'; }); await flushDrafts(); const linkedPodcastStories = stories.filter((story) => project.storyIds.includes(story.id) && resolveStoryCreationRecipe(story).id === 'podcast'); for (const linked of linkedPodcastStories) await completeRecipeProduction(store, linked.id, 'CHATTERBOX'); if (previewUrl) URL.revokeObjectURL(previewUrl); setPreviewUrl(URL.createObjectURL(new Blob([wav as unknown as BlobPart], { type: 'audio/wav' }))); setRendered(result); setLastPackage(packageBlob); await reload(); if (linkedPodcastStories[0]) navigate(`/greenlight/${linkedPodcastStories[0].id}`); else setNotice({ text: 'Episode package saved to the Media Bin. Link its podcast story to send it to Green Light.' }); } catch (error) { setNotice({ text: error instanceof Error ? error.message : 'The episode package did not finish.', error: true }); } finally { setBusy(''); setRenderProgress(undefined); } }

  if (!show || !project) return <section className="view on newsroom-room chatterbox-room"><div className="chatterbox-loading"><span>◖))</span><h1>Warming up Chatterbox…</h1><p>{notice?.text ?? 'Opening the show board and tape library.'}</p></div></section>;

  const projectProblems = [...new Set([...podcastProblems(project), ...episodeFindings.filter((finding) => finding.severity === 'BLOCKING').map((finding) => finding.message)])]; const clipSource = selectedClip ? audioUrls.get(selectedClip.assetId) : undefined;
  return <section className="view on newsroom-room chatterbox-room">
    <header className="chatterbox-hero"><div className="chatterbox-radio-mark"><i /><b>CB</b><span>96.7</span></div><div><span className="newsroom-eyebrow">CHATTERBOX PODCAST</span><h1>{show.title}</h1><p>Build an episode from newsroom stories, voices, music, and sound.</p></div><div className="chatterbox-project-pick"><label>Episode<select value={project.id} disabled={!!busy} onChange={(event) => { const next = projects.find((item) => item.id === event.target.value); if (next) void switchProject(next); }}>{starter && <option value={project.id}>{project.title} · starter</option>}{projects.map((item) => <option value={item.id} key={item.id}>{item.title} · {item.state.toLowerCase()}</option>)}</select></label><details ref={newEpisodeMenu}><summary>＋ New episode</summary><div className="chatterbox-format-menu">{PODCAST_FORMATS.map((format) => <button key={format.id} disabled={!!busy} onClick={() => void newEpisode(format.id)}><span><b>{format.title}</b><em>{format.hosts} · {clock(format.segments.reduce((sum, segment) => sum + segment.targetSec, 0))}</em></span><small>{format.promise}</small><i>{format.segments.map((segment) => segment.title).join(' → ')}</i></button>)}<button disabled={!!busy} onClick={() => void newEpisode('TRAILER')}><span><b>Show trailer</b><em>Short introduction · 01:10</em></span><small>Introduce Chatterbox before the first full episode.</small><i>Best moment → Meet the show → Listen next</i></button></div></details></div></header>
    <nav className="chatterbox-stations" aria-label="Podcast production stations">{STATIONS.map((item, index) => <button key={item.id} aria-current={station === item.id} onClick={() => setStation(item.id)}><span>{item.icon}</span><i>{index + 1}</i><b>{item.label}</b><small>{item.verb}</small></button>)}</nav>
    <div className="chatterbox-episode-tools"><span><b>{PODCAST_FORMATS.find((format) => format.id === project.formatId)?.title ?? (project.episodeType === 'TRAILER' ? 'Show trailer' : 'Open format')}</b><small>{clock(planDuration)} planned · {clock(duration)} in the cut</small></span><button onClick={() => setShowCoverStudio(true)}>▧ Cover</button><button className={episodeFindings.some((finding) => finding.severity === 'BLOCKING') ? 'needs-work' : ''} onClick={() => setShowEpisodeCheck(true)}>Episode Check <b>{episodeFindings.length}</b></button></div>
    <div className={`chatterbox-status ${notice?.error ? 'error' : ''} ${!notice && !dirty && !showDirty && !busy ? 'idle' : ''}`} role={notice?.error ? 'alert' : 'status'}><span className="chatterbox-status-light" /><p>{busy || (dirty || showDirty ? 'Saving changes…' : notice?.text) || (starter ? 'Add a story card or start editing. Your work saves when you make a change.' : 'All changes saved')}</p>{renderProgress !== undefined && <meter min={0} max={1} value={renderProgress} />}{notice && <button aria-label="Dismiss message" onClick={() => setNotice(undefined)}>×</button>}</div>
    {showEpisodeCheck && <ChatterboxEpisodeCheck findings={episodeFindings} onFocus={focusEpisodeFinding} onClose={() => setShowEpisodeCheck(false)} />}
    {showCoverStudio && <ChatterboxCoverStudio showTitle={show.title} episodeTitle={project.title} episodeNumber={project.episodeNumber} artworkMode={project.artworkMode} showCoverId={show.coverAssetId} episodeCoverId={project.artworkAssetId} effectiveCoverId={effectiveCoverId} choices={coverChoices} urls={audioUrls} onUseShow={() => commit((draft) => { draft.artworkMode = 'SHOW'; })} onUseEpisode={() => commit((draft) => { draft.artworkMode = 'EPISODE'; })} onSetShow={(assetId) => { commitShow((draft) => { draft.coverAssetId = assetId; }); commit((draft) => { draft.artworkMode = 'SHOW'; }); }} onChoose={(assetId) => commit((draft) => { draft.artworkAssetId = assetId; draft.artworkMode = 'EPISODE'; })} onUpload={(file) => void uploadCover(file)} onEditBlast={() => void editCoverInBlast()} onClose={() => setShowCoverStudio(false)} />}

    {station === 'RUNDOWN' && <div className="chatterbox-rundown">
      <aside className="chatterbox-show-card"><span className="newsroom-eyebrow">SHOW ID</span><label>Show name<input value={show.title} onChange={(event) => commitShow((draft) => { draft.title = event.target.value; })} /></label><label>What the show is about<textarea value={show.description} onChange={(event) => commitShow((draft) => { draft.description = event.target.value; })} /></label><label>Default voice<select value={show.defaultVoicePreset} onChange={(event) => commitShow((draft) => { draft.defaultVoicePreset = event.target.value as PodcastShow['defaultVoicePreset']; })}>{Object.entries(PODCAST_VOICE_PRESETS).map(([id, item]) => <option value={id} key={id}>{item.label}</option>)}</select></label><div className="chatterbox-show-numbers"><b>EP {project.episodeNumber ?? '—'}</b><span>{clock(planDuration)} planned</span><span>{project.storyIds.length} linked stories</span></div></aside>
      <main className="chatterbox-rundown-board"><div className="chatterbox-section-title"><div><span className="newsroom-eyebrow">TODAY’S RUNDOWN</span><h2>Build the show in order</h2></div><label>Episode title<input value={project.title} onChange={(event) => commit((draft) => { draft.title = event.target.value; })} /></label></div><div className="chatterbox-rundown-list">{project.segments.map((segment, index) => <article key={segment.id} style={{ '--segment-color': segment.color } as React.CSSProperties}><div className="chatterbox-segment-grip"><b>{String(index + 1).padStart(2, '0')}</b><span>⠿</span></div><div className="chatterbox-segment-body"><span>{segmentLabel(segment.kind)}{segment.storyId && <i>Linked story</i>}</span>{segment.purpose && <small className="chatterbox-segment-purpose">{segment.purpose}</small>}<input value={segment.title} aria-label={`Segment ${index + 1} title`} onChange={(event) => commit((draft) => { draft.segments[index]!.title = event.target.value; })} /><textarea value={segment.script} aria-label={`Segment ${index + 1} script`} placeholder="Script, intro, questions, or the words that hold this segment together…" onChange={(event) => commit((draft) => { draft.segments[index]!.script = event.target.value; })} /><div><label>Target <input type="number" min={5} max={3600} value={segment.targetSec} onChange={(event) => commit((draft) => { draft.segments[index]!.targetSec = Math.max(5, Number(event.target.value)); })} /> sec</label><input value={segment.notes} placeholder="Producer note" aria-label={`Segment ${index + 1} producer note`} onChange={(event) => commit((draft) => { draft.segments[index]!.notes = event.target.value; })} /></div></div><div className="chatterbox-segment-actions"><button aria-label="Move segment earlier" disabled={!index} onClick={() => moveSegment(segment.id, -1)}>↑</button><button aria-label="Move segment later" disabled={index === project.segments.length - 1} onClick={() => moveSegment(segment.id, 1)}>↓</button><button aria-label="Remove segment" onClick={() => commit((draft) => { draft.segments.splice(index, 1); draft.storyIds = [...new Set(draft.segments.map((item) => item.storyId).filter((id): id is string => !!id))]; })}>×</button></div></article>)}</div><div className="chatterbox-add-segment"><div><b>Add a story already in Chatter</b><select value={selectedStoryId} onChange={(event) => setSelectedStoryId(event.target.value)}><option value="">Choose a story…</option>{stories.map((story) => <option key={story.id} value={story.id}>{story.title} · {story.status.toLowerCase()}</option>)}</select><button disabled={!selectedStoryId} onClick={addStorySegment}>Add story card</button></div><div><b>Add another kind of segment</b>{PODCAST_SEGMENT_KINDS.filter((item) => item.kind !== 'STORY').map((item) => <button key={item.kind} title={item.hint} onClick={() => addSegment(item.kind)}>{item.label}</button>)}</div></div><footer><span>{project.segments.length} cards · {clock(planDuration)} target</span><button className="newsroom-button primary" onClick={() => setStation('RECORD')}>Rundown ready · Record →</button></footer></main>
    </div>}

    {station === 'RECORD' && <div className="chatterbox-record-room"><main className="chatterbox-mic-console"><div className="chatterbox-on-air"><span>{recorder.phase === 'RECORDING' ? 'ON AIR' : recorder.phase === 'COUNTDOWN' ? `${recorder.countdown}` : 'STANDBY'}</span><b>{clock(recorder.elapsed)}</b></div><div className="chatterbox-script-window"><span className="newsroom-eyebrow">RUNNING ORDER</span>{project.segments.map((segment, index) => <article key={segment.id}><b>{index + 1}. {segment.title}</b><p>{segment.script || segment.notes || 'No script on this card yet.'}</p></article>)}</div><div className="chatterbox-transport"><button className="chatterbox-record-key" disabled={!!busy || ['ASKING', 'SAVING'].includes(recorder.phase)} onClick={() => ['RECORDING', 'PAUSED', 'COUNTDOWN'].includes(recorder.phase) ? recorder.stop() : void recorder.start(countIn)}>{['RECORDING', 'PAUSED'].includes(recorder.phase) ? '■ STOP & SAVE' : recorder.phase === 'COUNTDOWN' ? 'CANCEL' : '● RECORD'}</button><button disabled={!['RECORDING', 'PAUSED'].includes(recorder.phase)} onClick={recorder.pause}>{recorder.phase === 'PAUSED' ? '▶ RESUME' : 'Ⅱ PAUSE'}</button><button disabled={!['RECORDING', 'PAUSED'].includes(recorder.phase)} onClick={recorder.mark}>⚑ MARK</button></div></main><aside className="chatterbox-input-rack"><span className="newsroom-eyebrow">INPUT RACK</span><h2>Mic and destination</h2><label>Record onto<select value={recordTrackId} onChange={(event) => setRecordTrackId(event.target.value)}>{project.tracks.filter((track) => track.kind === 'VOICE').map((track) => <option key={track.id} value={track.id}>{track.name}</option>)}</select></label><label>Microphone<select value={recorder.deviceId} onChange={(event) => recorder.setDevice(event.target.value)}><option value="">System default</option>{recorder.devices.map((device, index) => <option value={device.deviceId} key={device.deviceId}>{device.label || `Microphone ${index + 1}`}</option>)}</select></label><button className="newsroom-button primary" disabled={['RECORDING', 'COUNTDOWN', 'SAVING'].includes(recorder.phase)} onClick={() => void recorder.checkMicrophone()}>{recorder.phase === 'READY' ? 'Recheck microphone' : 'Check microphone'}</button><div className="chatterbox-meter"><i style={{ height: `${Math.max(2, Math.min(100, (recorder.level + 60) / 60 * 100))}%` }} /><span>−48</span><span>−24</span><span>−12</span><span>0</span></div><b className="chatterbox-level-readout">{recorder.phase === 'OFF' ? 'MIC OFF' : `${Math.round(recorder.level)} dBFS`}</b><label>Input gain · {recorder.gainDb > 0 ? '+' : ''}{recorder.gainDb} dB<input type="range" min={-12} max={12} value={recorder.gainDb} onChange={(event) => recorder.setGainDb(Number(event.target.value))} /></label><label>Count-in<select value={countIn} onChange={(event) => setCountIn(Number(event.target.value))}><option value={0}>Off</option><option value={3}>3 seconds</option><option value={5}>5 seconds</option></select></label><div className="chatterbox-import"><input ref={importPicker} hidden type="file" accept="audio/*,.wav,.mp3,.m4a,.webm,.ogg,.flac" onChange={(event) => { const file = event.target.files?.[0]; if (file) void importAudio(file); }} /><button onClick={() => importPicker.current?.click()}>Bring in a recording</button><small>Phone tape, remote guests, WAV, MP3, M4A, WebM, OGG, or FLAC.</small></div></aside></div>}

    {station === 'RECORD' && <RecordTakeBench clips={recordClips} urls={audioUrls} selectedId={selectedClipId} onSelect={setSelectedClipId} onUpdate={updateClip} onMove={arrangeRecordTakes} onPack={() => arrangeRecordTakes()} onRemove={removeRecordTake} onOpenCut={() => setStation('CUT')} />}

    {station === 'CUT' && <section className="chatterbox-cut-transport"><div className="chatterbox-cut-buttons"><button className="play" disabled={!!busy || !project.clips.length} onClick={timelinePlaying ? () => timelineAudio.current?.pause() : playFullCut}>{timelinePlaying ? 'Ⅱ Pause full cut' : rendered ? '▶ Play full cut' : '▶ Build + play full cut'}</button><button onClick={stopFullCut} disabled={!previewUrl}>■ Stop</button><button onClick={() => void makePreview()} disabled={!!busy || !project.clips.length}>{rendered ? '↻ Rebuild mix' : 'Build mix'}</button></div><div className="chatterbox-cut-scrub"><b>{clock(playhead)}</b><input aria-label="Full cut playhead" type="range" min={0} max={Math.max(.1, rendered?.audio.duration ?? duration)} step={.05} value={Math.min(playhead, rendered?.audio.duration ?? duration)} onChange={(event) => { const at = Number(event.target.value); setPlayhead(at); if (timelineAudio.current) timelineAudio.current.currentTime = at; }} /><b>{clock(rendered?.audio.duration ?? duration)}</b></div><audio ref={timelineAudio} src={previewUrl || undefined} onPlay={() => setTimelinePlaying(true)} onPause={() => setTimelinePlaying(false)} onEnded={() => setTimelinePlaying(false)} onTimeUpdate={(event) => setPlayhead(event.currentTarget.currentTime)} /><span>{rendered ? 'Playing the assembled episode from the yellow playhead.' : 'The first play builds every track, trim, fade, and mix move into one listening cut.'}</span></section>}

    {station === 'CUT' && <div className="chatterbox-cut-room"><aside className="chatterbox-palette"><span className="newsroom-eyebrow">TAPE SHELF</span><h2>Bring something into the cut</h2><div className="chatterbox-source-pick"><select value={selectedSourceId} onChange={(event) => setSelectedSourceId(event.target.value)}><option value="">Choose saved audio…</option>{choices.map((item) => <option value={item.assetId} key={item.assetId}>{item.source} · {item.title}</option>)}</select><button disabled={!selectedSourceId || !!busy} onClick={() => { const choice = choices.find((item) => item.assetId === selectedSourceId); if (choice) void addChoice(choice, selectedTrackId); }}>Place at end</button></div><div className="chatterbox-source-list">{choices.slice(0, 12).map((item) => <button key={item.assetId} onClick={() => void addChoice(item)}><span>{item.source}</span><b>{item.title}</b><small>{item.durationSec ? clock(item.durationSec) : 'Read duration when placed'}</small></button>)}</div><button className="newsroom-button" onClick={() => navigate('/booth')}>Open Booth for more tape ↗</button><button className="newsroom-button" onClick={() => navigate('/studio')}>Open Studio for music ↗</button></aside><main className="chatterbox-editor"><div className="chatterbox-editor-tools"><div><button onClick={() => { previewAudio.current?.pause(); setPlayhead(0); }}>■</button><button onClick={splitSelected} disabled={!selectedClip}>✂ Split</button><button disabled={!selectedClip} onClick={() => selectedClip && commit((draft) => { draft.clips = draft.clips.filter((clip) => clip.id !== selectedClip.id); })}>⌫ Remove</button></div><b>{clock(playhead)} / {clock(duration)}</b><label>Zoom<input type="range" min={3} max={18} value={zoom} onChange={(event) => setZoom(Number(event.target.value))} /></label></div><div className="chatterbox-timeline-scroll"><div className="chatterbox-timeline" style={{ width: timelineWidth }} onClick={(event) => { const rect = event.currentTarget.getBoundingClientRect(); setPlayhead(Math.max(0, (event.clientX - rect.left) / zoom)); }}><div className="chatterbox-ruler">{Array.from({ length: Math.ceil(timelineSec / 30) + 1 }, (_, index) => <span key={index} style={{ left: index * 30 * zoom }}>{clock(index * 30)}</span>)}</div><i className="chatterbox-playhead" style={{ left: playhead * zoom }} />{project.tracks.map((track) => <div className="chatterbox-timeline-row" key={track.id} style={{ '--track-color': track.color } as React.CSSProperties}><button className="chatterbox-track-head" aria-current={selectedTrack?.id === track.id} onClick={(event) => { event.stopPropagation(); setSelectedTrackId(track.id); }}><span>{TRACK_ICONS[track.kind]}</span><b>{track.name}</b><small>{track.muted ? 'muted' : `${track.volumeDb > 0 ? '+' : ''}${track.volumeDb} dB`}</small></button><div className="chatterbox-track-lane">{project.clips.filter((clip) => clip.trackId === track.id).map((clip) => <button key={clip.id} className={`chatterbox-audio-clip ${clip.muted ? 'muted' : ''}`} aria-current={selectedClipId === clip.id} style={{ left: clip.startSec * zoom, width: Math.max(28, podcastClipDuration(clip) * zoom) }} onPointerDown={(event) => beginClipDrag(event, clip)} onClick={(event) => { event.stopPropagation(); setSelectedClipId(clip.id); setSelectedTrackId(track.id); setPlayhead(clip.startSec); }}><b>{clip.name}</b><i>{Array.from({ length: 22 }, (_, index) => <span key={index} style={{ height: `${22 + (index * 17 + clip.id.length * 9) % 66}%` }} />)}</i><small>{clock(podcastClipDuration(clip))}</small></button>)}</div></div>)}</div></div></main><aside className="chatterbox-inspector"><span className="newsroom-eyebrow">EDIT BENCH</span>{selectedClip ? <><h2>{selectedClip.name}</h2>{clipSource && <audio ref={previewAudio} controls src={clipSource} onTimeUpdate={(event) => setPlayhead(selectedClip.startSec + Math.max(0, event.currentTarget.currentTime - selectedClip.trimInSec))} />}<div className="chatterbox-waveform">{wave.map((peak, index) => <i key={index} style={{ height: `${Math.max(3, peak * 100)}%` }} />)}</div><div className="chatterbox-clip-fields"><label>Track<select value={selectedClip.trackId} onChange={(event) => updateClip(selectedClip.id, { trackId: event.target.value })}>{project.tracks.map((track) => <option key={track.id} value={track.id}>{track.name}</option>)}</select></label><label>Starts<input type="number" min={0} step={.1} value={selectedClip.startSec} onChange={(event) => updateClip(selectedClip.id, { startSec: Math.max(0, Number(event.target.value)) })} /></label><label>Trim in<input type="number" min={0} max={selectedClip.trimOutSec - .05} step={.05} value={selectedClip.trimInSec} onChange={(event) => updateClip(selectedClip.id, { trimInSec: Number(event.target.value) })} /></label><label>Trim out<input type="number" min={selectedClip.trimInSec + .05} max={selectedClip.sourceDurationSec} step={.05} value={selectedClip.trimOutSec} onChange={(event) => updateClip(selectedClip.id, { trimOutSec: Number(event.target.value) })} /></label><label>Clip level<input type="range" min={-24} max={12} value={selectedClip.gainDb} onChange={(event) => updateClip(selectedClip.id, { gainDb: Number(event.target.value) })} /><b>{selectedClip.gainDb > 0 ? '+' : ''}{selectedClip.gainDb} dB</b></label><label>Fade in<input type="range" min={0} max={3} step={.05} value={selectedClip.fadeInSec} onChange={(event) => updateClip(selectedClip.id, { fadeInSec: Number(event.target.value) })} /></label><label>Fade out<input type="range" min={0} max={3} step={.05} value={selectedClip.fadeOutSec} onChange={(event) => updateClip(selectedClip.id, { fadeOutSec: Number(event.target.value) })} /></label></div><div className="chatterbox-transcript"><header><b>Transcript cut</b><span>{transcriptParts.length ? `${selectedClip.omittedRanges.length} cuts` : 'Waiting for transcript'}</span></header>{transcriptParts.length ? transcriptParts.map((part, index) => { const removed = selectedClip.omittedRanges.some((range) => range.start <= part.start + .01 && range.end >= part.end - .01); return <button key={index} className={removed ? 'removed' : ''} onClick={() => toggleTranscriptPart(part)}><small>{clock(part.start)}</small><span>{part.text}</span><i>{removed ? 'Put back' : 'Cut'}</i></button>; }) : <p>The on-device transcript appears here after processing. Waveform editing works while it finishes.</p>}</div></> : <div className="chatterbox-empty-bench"><span>✂</span><h2>Pick a clip</h2><p>Its waveform, trim handles, fades, level, and transcript will open here.</p></div>}</aside></div>}

    {station === 'MIX' && <div className="chatterbox-mix-room"><main className="chatterbox-mixer"><div className="chatterbox-section-title"><div><span className="newsroom-eyebrow">PAINTER’S PALETTE</span><h2>Shape the sound by intention</h2><p>Choose what the listener should hear. Open the numbers when you want them.</p></div><button className="newsroom-button primary" disabled={!!busy || !project.clips.length} onClick={() => void makePreview()}>{busy ? busy : 'Make a listening preview'}</button></div><div className="chatterbox-channel-strips">{project.tracks.map((track) => <article key={track.id} style={{ '--track-color': track.color } as React.CSSProperties}><header><span>{TRACK_ICONS[track.kind]}</span><div><b>{track.name}</b><small>{track.kind.toLowerCase()}</small></div></header><div className="chatterbox-strip-buttons"><button aria-pressed={track.muted} onClick={() => updateTrack(track.id, { muted: !track.muted })}>MUTE</button><button aria-pressed={track.solo} onClick={() => updateTrack(track.id, { solo: !track.solo })}>SOLO</button></div><label className="chatterbox-fader"><input type="range" orient="vertical" min={-36} max={12} value={track.volumeDb} onChange={(event) => updateTrack(track.id, { volumeDb: Number(event.target.value) })} /><b>{track.volumeDb > 0 ? '+' : ''}{track.volumeDb}</b><small>dB</small></label><label>Left / right<input type="range" min={-1} max={1} step={.1} value={track.pan} onChange={(event) => updateTrack(track.id, { pan: Number(event.target.value) })} /></label>{track.kind === 'VOICE' ? <div className="chatterbox-voice-palette"><b>Voice color</b>{Object.entries(PODCAST_VOICE_PRESETS).map(([id, item]) => <button key={id} aria-pressed={track.voicePreset === id} onClick={() => updateTrack(track.id, { voicePreset: id as PodcastTrack['voicePreset'] })}><span>{item.label}</span><small>{item.hint}</small></button>)}<label>How much<input type="range" min={0} max={1} step={.05} value={track.effectAmount} onChange={(event) => updateTrack(track.id, { effectAmount: Number(event.target.value) })} /></label></div> : <label className="chatterbox-duck"><input type="checkbox" checked={track.duckUnderVoice} onChange={(event) => updateTrack(track.id, { duckUnderVoice: event.target.checked })} /><span><b>Move under voices</b><small>Dip this track while somebody speaks.</small></span></label>}</article>)}</div></main><aside className="chatterbox-master"><span className="newsroom-eyebrow">MASTER</span><h2>Listening copy</h2><div className="chatterbox-master-meter"><i style={{ height: `${Math.min(100, Math.max(5, rendered ? (rendered.estimatedLufs + 40) / 40 * 100 : 18))}%` }} /><span>READY</span></div>{previewUrl ? <audio controls src={previewUrl} /> : <div className="chatterbox-speaker"><i /><i /><p>Make a preview to hear every track and palette choice together.</p></div>}<label>Podcast loudness<select value={project.targetLufs} onChange={(event) => commit((draft) => { draft.targetLufs = Number(event.target.value); })}><option value={-16}>Standard · −16 LUFS</option><option value={-18}>Gentler · −18 LUFS</option><option value={-14}>Louder · −14 LUFS</option></select></label><label>Peak ceiling<select value={project.truePeakDb} onChange={(event) => commit((draft) => { draft.truePeakDb = Number(event.target.value); })}><option value={-1}>Safe · −1 dB</option><option value={-2}>Extra room · −2 dB</option></select></label>{rendered && <dl><div><dt>Program level</dt><dd>{rendered.estimatedLufs.toFixed(1)} LUFS est.</dd></div><div><dt>Highest peak</dt><dd>{rendered.truePeakDb.toFixed(1)} dB</dd></div><div><dt>Master move</dt><dd>{rendered.appliedGainDb > 0 ? '+' : ''}{rendered.appliedGainDb.toFixed(1)} dB</dd></div></dl>}<label className="chatterbox-rights-check"><input type="checkbox" checked={!!project.musicRightsConfirmed} onChange={(event) => commit((draft) => { draft.musicRightsConfirmed = event.target.checked; })} /><span><b>Music is cleared</b><small>The crew made it, owns it, or has permission to use it here.</small></span></label><small>The meter estimates program loudness in this browser. The WAV master keeps full-quality audio for the final upload.</small></aside></div>}

    {station === 'PACKAGE' && <div className="chatterbox-package-room"><main><div className="chatterbox-package-title"><button className="chatterbox-package-art" onClick={() => setShowCoverStudio(true)} aria-label="Open Cover Studio">{effectiveCoverId && audioUrls.get(effectiveCoverId) ? <img src={audioUrls.get(effectiveCoverId)} alt="Episode art" /> : <><b>CB</b><span>{project.episodeNumber ?? 'EP'}</span></>}</button><div><span className="newsroom-eyebrow">EPISODE PACKAGE</span><input value={project.title} aria-label="Episode title" onChange={(event) => commit((draft) => { draft.title = event.target.value; })} /><p>{show.title} · {project.episodeType.toLowerCase()} episode · {clock(duration)}</p><button className="chatterbox-cover-link" onClick={() => setShowCoverStudio(true)}>Change cover</button></div></div><div className="chatterbox-metadata"><label>Episode description<textarea value={project.description} onChange={(event) => commit((draft) => { draft.description = event.target.value; })} placeholder="Tell listeners what they will hear and why it matters." /></label><div><label>Type<select value={project.episodeType} onChange={(event) => commit((draft) => { draft.episodeType = event.target.value as PodcastProject['episodeType']; })}><option value="FULL">Full episode</option><option value="BONUS">Bonus</option><option value="TRAILER">Trailer</option></select></label><label>Season<input type="number" min={1} value={project.seasonNumber ?? ''} onChange={(event) => commit((draft) => { draft.seasonNumber = event.target.value ? Number(event.target.value) : undefined; })} /></label><label>Episode<input type="number" min={1} value={project.episodeNumber ?? ''} onChange={(event) => commit((draft) => { draft.episodeNumber = event.target.value ? Number(event.target.value) : undefined; })} /></label><label className="chatterbox-explicit"><input type="checkbox" checked={project.explicit} onChange={(event) => commit((draft) => { draft.explicit = event.target.checked; })} /><span>Contains explicit material</span></label></div></div><section className="chatterbox-chapters"><header><div><span className="newsroom-eyebrow">CHAPTERS</span><h2>Listener bookmarks</h2></div><button onClick={() => commit((draft) => { draft.chapters = segmentChapters(draft.segments); })}>Make from rundown</button></header>{project.chapters.map((chapter, index) => <div key={chapter.id}><input type="number" min={0} value={chapter.atSec} onChange={(event) => commit((draft) => { draft.chapters[index]!.atSec = Number(event.target.value); })} /><b>{clock(chapter.atSec)}</b><input value={chapter.title} onChange={(event) => commit((draft) => { draft.chapters[index]!.title = event.target.value; })} /><button onClick={() => commit((draft) => { draft.chapters.splice(index, 1); })}>×</button></div>)}</section><section className="chatterbox-handoff"><div><span className="newsroom-eyebrow">HANDOFF</span><h2>{project.state === 'REVIEW' ? 'Waiting at Green Light' : projectProblems.length ? `${projectProblems.length} things before handoff` : 'Ready to package'}</h2>{projectProblems.length ? <ul>{projectProblems.map((problem) => <li key={problem}>{problem}</li>)}</ul> : <p>The listening master, cover, transcript, chapters, notes, and episode record will travel together.</p>}</div><div><button className="newsroom-button primary" disabled={!!busy || !!projectProblems.length} onClick={() => void makePackage()}>{busy || (project.state === 'REVIEW' ? 'Rebuild package' : 'Build package + send to Green Light')}</button>{lastPackage && <button className="newsroom-button" onClick={() => download(lastPackage, `${safeName(project.title)}-episode.zip`)}>Download episode ZIP</button>}<button className="newsroom-button" onClick={() => navigate('/files')}>Open Media Bin ↗</button></div></section></main><aside className="chatterbox-listen-proof"><span className="newsroom-eyebrow">LISTENING PROOF</span><div className="chatterbox-proof-player">{effectiveCoverId && audioUrls.get(effectiveCoverId) && <img className="chatterbox-proof-cover" src={audioUrls.get(effectiveCoverId)} alt="" />}<div><b>CB</b><span>CHATTERBOX</span></div><h2>{project.title}</h2><p>{project.description || 'The episode description will appear here.'}</p>{previewUrl ? <audio controls src={previewUrl} /> : <button onClick={() => void makePreview()} disabled={!project.clips.length || !!busy}>▶ Make and play preview</button>}<ol>{project.chapters.map((chapter) => <li key={chapter.id}><b>{clock(chapter.atSec)}</b><span>{chapter.title}</span></li>)}</ol></div><div className="chatterbox-package-contents"><b>Inside the package</b><span>High-quality WAV master</span><span>Square cover art</span><span>Show notes</span><span>Chapter file</span><span>Transcript</span><span>Episode metadata</span></div></aside></div>}
  </section>;
}
